#include <iostream>
using namespace std;

long long prefixCount(long long n, long long len, long long pos) {
    if (n == 0 || pos <= 0) return 0;
    if (pos >= len) return n;
    if (n == 1) return 1;

    long long halfLen = len / 2;
    long long half = n / 2;

    if (pos <= halfLen)
        return prefixCount(half, halfLen, pos);

    return half + (n & 1LL) +
           prefixCount(half, halfLen, pos - halfLen - 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, l, r;
    while (cin >> n >> l >> r) {
        long long len = 1;
        for (long long t = n; t > 1; t /= 2)
            len = len * 2 + 1;

        cout << prefixCount(n, len, r) -
                prefixCount(n, len, l - 1) << '\n';
    }

    return 0;
}

