using int64 = long long;

int64 prefixOnes(int64 n, int64 len, int64 pos) {
    if (pos <= 0 || n == 0) return 0;
    if (pos >= len) return n;

    int64 childLen = (len - 1) / 2;

    if (pos <= childLen)
        return prefixOnes(n / 2, childLen, pos);

    return n / 2 + (n & 1) +
           prefixOnes(n / 2, childLen, pos - childLen - 1);
}

