using namespace std;

long long prefixOnes(long long n, long long len, long long pos) {
    if (pos <= 0) return 0;
    if (pos >= len) return n;
    if (n <= 1) return n;

    long long half = len / 2;

    if (pos <= half)
        return prefixOnes(n / 2, half, pos);

    long long result = n / 2;
    if (pos == half + 1)
        return result + (n & 1);

    return result + (n & 1)
           + prefixOnes(n / 2, half, pos - half - 1);
}

