#include <cstdio>

using namespace std;

long long prefixOnes(long long n, long long len, long long pos) {
    if (pos <= 0 || n == 0) return 0;
    if (pos >= len) return n;
    if (n == 1) return 1;

    long long halfLen = len / 2;
    long long halfN = n / 2;

    if (pos <= halfLen)
        return prefixOnes(halfN, halfLen, pos);

    return halfN + (n & 1LL) +
           prefixOnes(halfN, halfLen, pos - halfLen - 1);
}

int main() {
    long long n, l, r;

    while (scanf("%lld%lld%lld", &n, &l, &r) == 3) {
        long long length = 1;
        for (long long t = n; t > 1; t /= 2)
            length = length * 2 + 1;

        long long answer = prefixOnes(n, length, r) -
                           prefixOnes(n, length, l - 1);

        printf("%lld\n", answer);
    }

    return 0;
}

#include <cstdio>

using namespace std;

long long countPrefix(long long n, long long len, long long pos) {
    if (pos <= 0 || n == 0) return 0;
    if (pos >= len) return n;
    if (n == 1) return 1;

    long long halfLen = (len - 1) / 2;

    if (pos <= halfLen)
        return countPrefix(n / 2, halfLen, pos);

    long long result = n / 2 + n % 2;
    if (pos == halfLen + 1)
        return result;

    return result + countPrefix(n / 2, halfLen, pos - halfLen - 1);
}

int main() {
    long long n, l, r;

    while (scanf("%lld%lld%lld", &n, &l, &r) == 3) {
        long long len = 1;
        for (long long t = n; t > 1; t /= 2)
            len = len * 2 + 1;

        long long answer = countPrefix(n, len, r)
                         - countPrefix(n, len, l - 1);

        printf("%lld\n", answer);
    }

    return 0;
}

